const source = $('Execute Workflow Trigger').item.json || {};
const payload = source.payload || {};
const message = source.message || payload.message || payload.body?.message || {};
const chatId = source.chatId || message.chat?.id || payload.chatId || '';
const raw = String(source.rawText || message.text || payload.text || '').trim();
const folderId = source.folderId || payload.folderId || 'root';
const mimeType = source.mimeType || payload.mimeType || 'text/plain';

const providedName = String(source.fileName || payload.fileName || '').trim();
let content = source.content ?? payload.content;
const extracted = raw.replace(/^(tao file|tao tep|create file)\s*/i, '').trim();
let fileName = providedName;

if (!fileName && extracted) {
  const match = extracted.match(/^(.*?)(?:\s+(?:noi dung|content)\s*[:=-]?\s*(.*))?$/i);
  if (match) {
    fileName = String(match[1] || '').trim();
    if (content === undefined && match[2] !== undefined) {
      content = match[2];
    }
  }
}

const hasTarget = Boolean(fileName);

if (!fileName) {
  fileName = 'ghi-chu.txt';
}

if (!/\.[a-z0-9]{1,8}$/i.test(fileName) && mimeType === 'text/plain') {
  fileName += '.txt';
}

content = String(content ?? '');

return [{
  json: {
    ...source,
    payload,
    message,
    chatId,
    raw,
    folderId,
    mimeType,
    fileName,
    content,
    hasTarget,
    response: hasTarget
      ? ''
      : '📄 <b>Tao file</b>\n\nVi du: tao file ghi-chu.txt noi dung Xin chao',
  },
}];

const source = $('Prepare Action').item.json || {};
const content = String(source.content ?? '');
const mimeType = String(source.mimeType || 'text/plain');
const fileName = String(source.fileName || 'ghi-chu.txt');

return [{
  json: {
    ...source,
    binaryPropertyName: 'data',
    contentLength: content.length,
  },
  binary: {
    data: {
      data: Buffer.from(content, 'utf8').toString('base64'),
      mimeType,
      fileName,
    },
  },
}];

const escapeHtml = (value = '') => String(value)
  .replace(/&/g, '&amp;')
  .replace(/</g, '&lt;')
  .replace(/>/g, '&gt;')
  .replace(/\"/g, '&quot;');

const source = $('Build File Binary').item.json || $('Prepare Action').item.json || {};
const item = $input.item.json || {};
const fileName = item.name || source.fileName || 'Khong ro ten';
const fileId = item.id || '';
const link = item.webViewLink || '';
const sizeLabel = Number.isFinite(Number(source.contentLength)) ? `${Number(source.contentLength)} ky tu` : '';

let text = '✅ <b>Da tao file tren Google Drive</b>\n\n';
text += '<b>' + escapeHtml(fileName) + '</b>\n';
if (fileId) text += 'ID: <code>' + escapeHtml(fileId) + '</code>\n';
if (sizeLabel) text += 'Noi dung: ' + escapeHtml(sizeLabel) + '\n';
if (link) text += '🔗 <a href="' + escapeHtml(link) + '">Mo file</a>';

return [{ json: { chatId: source.chatId, text: text.trim() } }];
